/* ==== 시안 style 블록 3 ==== */
/* 11/13 글자 크기 단계: 11 배지, 12 캡션, 13 보조, 14 UI 본문, 15 읽는 본문, 16 강조, 18 카드 제목, 20 섹션 제목, 24 큰 섹션, 28 상세 제목, 32 목록 페이지 제목, 40 큰 숫자, 48 배너 */
/* 11/13 글꼴 Pretendard로 통일 */
:root{--font:'Pretendard Variable',Pretendard,-apple-system,BlinkMacSystemFont,system-ui,'Apple SD Gothic Neo','Malgun Gothic',sans-serif}
body,button,input,select,textarea{font-family:var(--font)}

:root{--ink:#1c1c1c;--ink2:#555;--ink3:#777;--line:#d1d1d1;--line2:#e3e3e3;--fill:#f1f1ef;--fill2:#e3e3e0;--bg:#fff}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.6 var(--font)}
a{color:inherit}
button,input,textarea{font:inherit;color:inherit}
:focus-visible{outline:3px solid var(--brand);outline-offset:2px}
.wrap{max-width:1180px;margin:0 auto;padding:0 28px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
.ph{background:repeating-linear-gradient(135deg,var(--fill) 0 10px,#f8f8f6 10px 20px);border:1px dashed #c8c8c4}
.lowfi-note{background:var(--fillc);color:#fff;font-size:13px;text-align:center;padding:6px}

/* header */
.hd{position:sticky;top:0;z-index:10;background:#fff;border-bottom:1px solid var(--line)}
.hd .wrap{height:60px;display:flex;align-items:center;gap:16px;max-width:1280px}
.logo{font-weight:900;font-size:16px;white-space:nowrap;text-decoration:none;display:flex;align-items:center;gap:8px;flex:none}
.logo i{width:22px;height:22px;border-radius:6px;background:var(--fillc);transform:rotate(-8deg)}
.gnav{flex:1;min-width:0;display:flex;justify-content:center;gap:0}
.gnav a{height:60px;display:flex;align-items:center;padding:0 9px;text-decoration:none;color:var(--ink3);font-size:13px;white-space:nowrap;position:relative}
.gnav a{gap:5px}
.gnav .ni,.util .ni{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none}
.gnav a:hover{color:var(--ink)}
.gnav a[aria-current=page]{color:var(--ink);font-weight:700}
.gnav a[aria-current=page]::after{content:"";position:absolute;left:9px;right:9px;bottom:0;height:2px;background:var(--fillc);border-radius:3px 3px 0 0}
.gnav .sep{width:1px;height:16px;background:var(--line);align-self:center;margin:0 4px;flex:none}
.util{display:flex;align-items:center;gap:2px;flex:none;font-size:13px;white-space:nowrap}
.util a{text-decoration:none;padding:6px 8px;border-radius:8px}
.util a:hover{background:var(--fill)}
.av{width:30px;height:30px;flex:none;border-radius:50%;background:#c4c4bf}

/* common */
.page{display:none}.page.on{display:block}
.ptop{padding:44px 0 28px;border-bottom:1px solid var(--line);margin-bottom:28px;display:flex;justify-content:space-between;align-items:flex-end;gap:20px;flex-wrap:wrap}
.ptop .k{font-size:13px;font-weight:700;letter-spacing:1.4px;color:var(--ink3);text-transform:uppercase}
.ptop h1{margin:4px 0 4px;font-size:32px;font-weight:900;letter-spacing:-1px}
.ptop p{margin:0;color:var(--ink2);max-width:620px}
.btn{height:42px;padding:0 18px;border-radius:999px;border:1.5px solid var(--brand);background:#fff;font-weight:700;font-size:14px;cursor:pointer;display:inline-flex;align-items:center;gap:6px;text-decoration:none;white-space:nowrap}
.btn:hover{background:var(--fill)}
.btn.pri{background:var(--fillc);color:#fff}
.btn.pri:hover{background:var(--brand-800)}
.btn.sm{height:34px;padding:0 13px;font-size:13px}
.tabs{display:flex;gap:4px;background:var(--fill);border-radius:999px;padding:4px;width:max-content;margin-bottom:22px}
.tabs button{height:36px;padding:0 16px;border:0;background:none;border-radius:999px;cursor:pointer;color:var(--ink2);font-size:14px}
.tabs button[aria-selected=true]{background:#fff;color:var(--ink);font-weight:700;box-shadow:0 0 0 1px var(--line)}
@media(max-width:600px){.tabs{max-width:100%;overflow-x:auto;scrollbar-width:none}.tabs button{flex:none;padding:0 12px}}
.chips{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:22px}
.chip{height:34px;padding:0 13px;border-radius:999px;border:1.5px solid #d6e1e9;background:#fff;font-size:14px;cursor:pointer}
.chip[aria-pressed=true]{background:var(--fillc);border-color:var(--brand);color:#fff;font-weight:700}
.rows{list-style:none;margin:0;padding:0;border-bottom:1px solid var(--line)}
.rows li{display:flex;align-items:center;gap:14px;min-height:64px;border-top:1px solid var(--line);padding:10px 0}
.rows .t{flex:1;min-width:0}.rows .t b{display:block}.rows .t span{font-size:14px;color:var(--ink2)}
.mono{width:40px;height:40px;border-radius:10px;background:var(--fill2);display:flex;align-items:center;justify-content:center;font-weight:700;flex:none}
.card{border:1.5px solid #d6e1e9;border-radius:18px;padding:18px;display:flex;flex-direction:column;gap:8px;background:#fff}
.card h3{margin:0;font-size:16px}
.card p{margin:0;font-size:14px;color:var(--ink2)}
.pill{font-size:12px;border:1px solid #d6e1e9;border-radius:999px;padding:1px 9px;color:var(--ink2)}
.ft{margin-top:auto;padding-top:10px;border-top:1px solid var(--line2);display:flex;align-items:center;gap:10px;font-size:13px;color:var(--ink3)}
.ft .btn{margin-left:auto}
.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.g4{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.sec{margin:0 0 56px}
.sec-h{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:12px}
.sec-h h2{margin:0;font-size:20px}
.sec-h a{font-size:14px;color:var(--ink2)}
.note{font-size:13px;color:var(--ink3);border-left:3px solid var(--line);padding-left:10px;margin-top:10px}

/* home */
.hero{text-align:center;padding:84px 0 72px;background:var(--fill);margin-bottom:56px;position:relative;overflow:hidden}
.hero h1{margin:0 0 10px;font-size:48px;font-weight:900;letter-spacing:-2px;line-height:1.1}
.hero p{margin:0 0 28px;color:var(--ink2)}
.search{display:flex;gap:10px;max-width:760px;margin:0 auto}
.search label{flex:1;height:60px;border:2px solid var(--brand);border-radius:999px;background:#fff;display:flex;align-items:center;padding:0 22px}
.search input{flex:1;border:0;outline:0;background:none;font-size:16px}
.search .btn{height:60px;padding:0 30px}
.blob{position:absolute;border-radius:30px;background:var(--fill2)}
.menu-map{display:grid;grid-template-columns:repeat(5,1fr);border-top:1.5px solid var(--brand);border-bottom:1px solid var(--line);margin-bottom:56px}
.menu-map a{padding:22px 18px 24px;border-left:1px solid var(--line);text-decoration:none;display:flex;flex-direction:column;gap:6px}
.menu-map a:first-child{border-left:0;padding-left:0}
.menu-map .ic{width:36px;height:36px;border-radius:10px;background:var(--fill2)}
.menu-map b{font-size:18px}
.menu-map span{font-size:14px;color:var(--ink2)}
.menu-map em{font-style:normal;font-size:13px;font-weight:700;margin-top:auto}
.menu-map a:hover b{text-decoration:underline}
.split{display:grid;grid-template-columns:1fr 1fr;gap:64px}
.launch-band{display:flex;align-items:center;gap:24px;background:var(--fillc);color:#fff;border-radius:24px;padding:32px 36px;margin-bottom:72px}
.launch-band h2{margin:0;font-size:24px}
.launch-band p{margin:4px 0 0;color:#c4c4c4;font-size:14px}
.launch-band .btn{margin-left:auto;background:#fff;color:var(--ink);border-color:#fff}

/* store */
.store{display:grid;grid-template-columns:240px minmax(0,1fr);gap:32px}.store>*{min-width:0}
.filters fieldset{border:0;border-bottom:1px solid var(--line);margin:0;padding:14px 0}
.filters legend{font-weight:700;font-size:14px;padding:0;margin-bottom:6px}
.filters label{display:flex;gap:8px;align-items:center;font-size:14px;min-height:32px}
.filters input{accent-color:var(--brand);width:17px;height:17px}

/* toolkit */
.prompt{font-size:14px;background:var(--fill);border-radius:10px;padding:12px;color:var(--ink);white-space:pre-wrap;font-family:var(--font)}

/* maker lab */
.journey{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border:1.5px solid var(--brand);border-radius:20px;overflow:hidden;margin-bottom:48px}
.step{padding:24px 22px;border-left:1px solid var(--line);display:flex;flex-direction:column;gap:8px;min-height:230px}
.step:first-child{border-left:0}
.step .n{width:30px;height:30px;border-radius:50%;border:1.5px solid var(--brand);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:14px}
.step h3{margin:4px 0 0;font-size:18px}
.step p{margin:0;font-size:14px;color:var(--ink2);flex:1}
.step.hl{background:var(--fill)}

/* idea board: post-it */
.flow{display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:13px;color:var(--ink2);margin:-8px 0 24px}
.flow b{border:1.5px solid var(--brand);border-radius:999px;padding:3px 11px;color:var(--ink);font-size:13px;background:#fff}
.flow b.hl{background:var(--fillc);color:#fff}
.flow .fr{border-style:dashed;color:var(--ink2)}
.composer{display:flex;gap:16px;align-items:flex-start;margin-bottom:28px;flex-wrap:wrap}
.note-new{width:280px;min-height:200px;background:#f3eecf;border:1.5px dashed #b9b29a;padding:16px;display:flex;flex-direction:column;gap:8px;transform:rotate(-1.5deg)}
.note-new textarea{flex:1;min-height:92px;border:0;background:transparent;resize:none;font-size:16px;outline:0}
.note-new .row{display:flex;gap:6px;flex-wrap:wrap}
.note-new select{height:32px;border:1px solid #b9b29a;background:#fffbea;border-radius:6px;font-size:13px}
.composer .tip{flex:1;min-width:240px;font-size:14px;color:var(--ink2)}
.composer .tip ul{margin:6px 0 0;padding-left:18px}
.wall{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:22px;margin-bottom:56px}
.sticky{min-height:190px;padding:16px 16px 12px;display:flex;flex-direction:column;gap:6px;box-shadow:0 1px 0 rgba(0,0,0,.08),0 6px 14px rgba(0,0,0,.06);position:relative}
.sticky:nth-child(4n+1){background:#f3eecf;transform:rotate(-1.2deg)}
.sticky:nth-child(4n+2){background:#e9ece4;transform:rotate(1deg)}
.sticky:nth-child(4n+3){background:#ecebe6;transform:rotate(-.6deg)}
.sticky:nth-child(4n){background:#f1ece6;transform:rotate(1.4deg)}
.sticky::before{content:"";position:absolute;top:-8px;left:50%;width:56px;height:16px;margin-left:-28px;background:rgba(200,200,196,.7)}
.sticky b{font-size:16px;line-height:1.35}
.sticky .who{font-size:13px;color:var(--ink2)}
.sticky .acts{margin-top:auto;display:flex;align-items:center;gap:6px}
.sticky .acts .btn{height:30px;padding:0 10px;font-size:13px;background:rgba(255,255,255,.7)}
.sticky .acts .mini{margin-left:auto;border:0;background:none;font-size:12px;color:var(--ink2);text-decoration:underline;cursor:pointer}
.sticky .gauge{height:5px;background:rgba(0,0,0,.08);border-radius:3px;overflow:hidden}
.sticky .gauge i{display:block;height:100%;background:var(--fillc)}
.ready{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:56px}
.ready .card{border-color:var(--brand)}
.ready .badge{align-self:flex-start;font-size:12px;font-weight:700;background:var(--fillc);color:#fff;border-radius:999px;padding:2px 10px}
.ready ul{margin:0;padding-left:18px;font-size:13px;color:var(--ink2)}
.fridge{border:2px dashed #b8c0c4;border-radius:22px;padding:22px;background:repeating-linear-gradient(0deg,#f4f6f7 0 28px,#eef1f2 28px 29px);margin-bottom:56px}
.fridge .shelf{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:14px}
.frozen{background:#fff;border:1px solid #cfd6d9;border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:6px;opacity:.9}
.frozen b{font-size:15px}
.frozen .why{font-size:12px;border:1px solid #cfd6d9;border-radius:999px;padding:1px 9px;align-self:flex-start;color:var(--ink2)}
.frozen .when{font-size:13px;color:var(--ink3)}
.frozen .btn{align-self:flex-start;margin-top:4px}

/* agent detail (app store style) */
.ad-top{display:flex;gap:24px;align-items:flex-start;padding:36px 0 28px;border-bottom:1px solid var(--line)}
.ad-icon{width:112px;height:112px;border-radius:26px;background:var(--fill2);display:flex;align-items:center;justify-content:center;font-size:40px;font-weight:900;flex:none}
.ad-top h1{margin:0;font-size:28px;font-weight:900;letter-spacing:-.8px}
.ad-top .sub{color:var(--ink2);font-size:15px;margin:2px 0 14px}
.ad-meta{display:grid;grid-template-columns:repeat(5,auto);justify-content:start;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:20px 0 32px}
.ad-meta div{padding:12px 28px 12px 0;margin-right:28px;border-right:1px solid var(--line)}
.ad-meta div:last-child{border-right:0}
.ad-meta small{display:block;font-size:12px;color:var(--ink3)}
.ad-meta b{font-size:18px}
.shots{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:40px}
.shots span{aspect-ratio:16/10;border-radius:14px}
.whatsnew{border:1.5px solid var(--brand);border-radius:18px;padding:22px;margin-bottom:40px}
.whatsnew .vh{display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap}
.whatsnew h2{margin:0;font-size:20px}
.whatsnew ul{margin:10px 0 0;padding-left:18px}
.whatsnew details{margin-top:16px;border-top:1px solid var(--line);padding-top:12px}
.whatsnew summary{cursor:pointer;font-weight:700;font-size:14px}
.vlist{list-style:none;padding:0;margin:8px 0 0}
.vlist li{display:grid;grid-template-columns:90px 100px 1fr;gap:12px;padding:8px 0;border-top:1px solid var(--line2);font-size:14px}
.rating{display:grid;grid-template-columns:160px 1fr;gap:28px;align-items:center;margin-bottom:20px}
.rating .big{font-size:48px;font-weight:900;line-height:1}
.bars div{display:grid;grid-template-columns:24px 1fr;gap:8px;align-items:center;font-size:12px;color:var(--ink2)}
.bars i{display:block;height:6px;background:var(--fill2);border-radius:3px;overflow:hidden}.bars i b{display:block;height:100%;background:var(--fillc)}
.info{width:100%;border-collapse:collapse;font-size:14px}
.info th{text-align:left;font-weight:400;color:var(--ink3);width:120px;padding:10px 0;border-top:1px solid var(--line)}
.info td{padding:10px 0;border-top:1px solid var(--line)}

/* builder path */
.paths{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:48px}
.path{border:1.5px solid #d6e1e9;border-radius:20px;padding:22px;display:flex;flex-direction:column;gap:10px}
.path.hl{border-color:var(--brand)}
.path h3{margin:0;font-size:18px}
.path ol{margin:0;padding-left:20px;font-size:14px;color:var(--ink2)}
.path ol li{margin:3px 0}
@media (max-width:960px){.ready,.paths{grid-template-columns:1fr}.ad-meta{grid-template-columns:repeat(3,auto)}.rating{grid-template-columns:1fr}}
@media (max-width:600px){.shots{grid-template-columns:1fr}.ad-top{flex-direction:column}.vlist li{grid-template-columns:1fr}.note-new{width:100%}}

/* launch desk drawer */
.scrim{position:fixed;inset:0;background:rgba(0,0,0,.35);display:none;z-index:30}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(440px,100%);background:#fff;z-index:31;transform:translateX(100%);transition:transform .25s;display:flex;flex-direction:column;border-left:1px solid var(--line)}
.drawer.on{transform:none}.scrim.on{display:block}
.dh{height:64px;display:flex;align-items:center;gap:10px;padding:0 18px;border-bottom:1px solid var(--line)}
.dh b{flex:1}
.dh button{border:0;background:none;font-size:20px;cursor:pointer;width:40px;height:40px;border-radius:8px}
.chat{flex:1;overflow:auto;padding:18px;display:flex;flex-direction:column;gap:12px;background:var(--fill)}
.msg{max-width:85%;padding:10px 14px;border-radius:14px;font-size:14px;background:#fff;border:1px solid #d6e1e9}
.msg.me{align-self:flex-end;background:var(--fillc);color:#fff;border-color:var(--brand)}
.opts{display:flex;gap:6px;flex-wrap:wrap}
.opts button{height:32px;padding:0 12px;border-radius:999px;border:1.5px solid var(--brand);background:#fff;cursor:pointer;font-size:13px}
.dinput{display:flex;gap:8px;padding:12px;border-top:1px solid var(--line)}
.dinput input{flex:1;height:44px;border:1.5px solid #d6e1e9;border-radius:10px;padding:0 12px}

.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:var(--fillc);color:#fff;padding:10px 16px;border-radius:8px;font-size:14px;opacity:0;transition:.2s;pointer-events:none;z-index:40}
.toast.on{opacity:1}
footer{border-top:1px solid var(--line);padding:24px 0;font-size:13px;color:var(--ink3)}

@media (max-width:1100px){.gnav a{padding:0 6px;gap:4px}.gnav a[aria-current=page]::after{left:7px;right:7px}.util .lbl{display:none}}
@media (max-width:820px){.gnav a{font-size:12px;padding:0 5px}.gnav a[aria-current=page]::after{left:5px;right:5px}.logo{font-size:0;gap:0}.gnav .sep{display:none}}
@media (max-width:960px){
  .menu-map{grid-template-columns:repeat(2,1fr)}.menu-map a{border-left:0;padding-left:0;border-top:1px solid var(--line)}
  .split,.store{grid-template-columns:minmax(0,1fr)}
  .g3,.g4{grid-template-columns:1fr 1fr}
  .journey{grid-template-columns:1fr 1fr}
  .hero h1{font-size:32px}
}
@media (max-width:600px){
  .gnav{justify-content:flex-start;overflow-x:auto;scrollbar-width:none}.av{display:none}
  .wrap{padding:0 16px}.g3,.g4,.journey{grid-template-columns:1fr}
  .search{flex-direction:column}.search .btn{height:52px}
  .launch-band{flex-direction:column;align-items:flex-start}.launch-band .btn{margin-left:0}
  .util .lbl{display:none}
}
@media (prefers-reduced-motion:reduce){*{transition:none!important}}
.ccard{text-decoration:none;display:flex;flex-direction:column;gap:12px;padding:20px}
.cc-top{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:13px;color:var(--ink2)}
.cc-ind{font-weight:700;color:var(--ink)}
.cc-dept{border:1px solid #d6e1e9;border-radius:999px;padding:1px 9px;background:var(--fill);color:var(--ink);white-space:nowrap}
.ccard h3{font-size:18px;margin:0}
.cc-k{display:block;font-size:11px;font-weight:700;letter-spacing:.4px;color:var(--ink2);margin-bottom:4px}
.cc-pain{background:var(--fill);border-radius:10px;padding:12px 14px;font-size:14px;line-height:1.5;color:var(--ink)}
.cc-sol{border:1.5px solid var(--brand);border-radius:10px;padding:12px 14px}
.cc-sol .cc-k{color:var(--ink)}
.cc-made{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:6px}
.cc-made li{display:flex;gap:6px;align-items:center;font-size:14px;color:var(--ink)}
.cc-ft{display:flex;justify-content:flex-end;margin-top:auto;font-size:13px}
.cc-top>span:first-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}

.ctable{background:#fff;border:1px solid #d6e1e9;border-radius:12px;overflow:hidden}
.ct-row{display:grid;grid-template-columns:64px 70px 120px 1.3fr 1.6fr 140px 90px 24px;gap:14px;align-items:center;padding:14px 16px;border-bottom:1px solid var(--line);font-size:14px;color:var(--ink);text-decoration:none}
.ct-row:last-child{border-bottom:0}
a.ct-row:hover{background:#fafaf8}
.ct-head{background:var(--fill);font-size:13px;font-weight:700;color:var(--ink2);border-bottom:1px solid var(--brand);padding:11px 16px}
.ct-title{font-weight:700}.ct-ind{font-weight:700}
.ct-pain{color:#444}
.ct-sol{display:flex;gap:5px;flex-wrap:wrap}.ct-sol .pill{border-color:var(--brand);color:var(--ink);font-weight:700}
.ct-when{color:var(--ink2);font-size:13px}
.ct-go{font-weight:700;text-align:right}
@media(max-width:900px){.ct-head{display:none}.ct-row{grid-template-columns:1fr 1fr;gap:6px 12px}.ct-row>span[data-l]::before{content:attr(data-l);display:block;font-size:11px;color:var(--ink2);font-weight:700}.ct-title,.ct-pain{grid-column:1/-1}.ct-go{display:none}}

/* ===== UX pass (11/11) ===== */
.crumb{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:14px;color:var(--ink2);margin:22px 0 0}
.crumb a{color:var(--ink2)}.crumb span[aria-current]{color:var(--ink);font-weight:700}
.dh2{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;flex-wrap:wrap;padding:20px 0 24px;border-bottom:1px solid var(--line)}
.dh2 h1{font-size:28px;line-height:1.25;margin:8px 0 6px}
.dh2 .meta{display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:14px;color:var(--ink2)}
.dgrid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:40px;margin-top:28px}
.dgrid aside{display:flex;flex-direction:column;gap:18px}
.box{border:1px solid #d6e1e9;border-radius:12px;padding:18px 20px;background:#fff}
.box h2,.box h3{font-size:15px;margin:0 0 10px}
.pp{background:var(--fill);border-radius:12px;padding:18px 20px;font-size:18px;line-height:1.55}
.pp small,.solbox small{display:block;font-size:12px;font-weight:700;letter-spacing:.4px;color:var(--ink2);margin-bottom:6px}
.solbox{border:1.5px solid var(--brand);border-radius:12px;padding:16px 20px;margin-top:14px}
.solbox li{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line);font-size:15px}
.solbox li:last-child{border-bottom:0}
.solbox ul{list-style:none;margin:0;padding:0}
.steps3{counter-reset:s;list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:12px}
.steps3 li{counter-increment:s;display:grid;grid-template-columns:32px 1fr;gap:12px;font-size:15px;line-height:1.55}
.steps3 li::before{content:counter(s);width:28px;height:28px;border-radius:50%;border:1.5px solid var(--brand);display:flex;align-items:center;justify-content:center;font:700 13px var(--font)}
.kv{width:100%;border-collapse:collapse;font-size:14px}.kv th{text-align:left;color:var(--ink2);font-weight:400;width:88px;padding:7px 0;vertical-align:top}.kv td{padding:7px 0}
.dsec{margin-top:34px}.dsec>h2{font-size:20px;margin:0 0 14px}
/* search */
.sbar{display:flex;gap:10px;margin:22px 0 8px}.sbar input{flex:1;height:52px;border:1.5px solid var(--brand);border-radius:999px;padding:0 22px;font-size:16px}
.sbar .btn{height:52px;padding:0 24px}
.sjump{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0 6px}
.sjump a{border:1px solid #d6e1e9;border-radius:999px;padding:6px 14px;font-size:14px;text-decoration:none;color:var(--ink);min-height:36px;display:inline-flex;align-items:center;gap:6px}
.sjump a b{font-family:var(--font)}
.sgroup{margin-top:30px}.sgroup .sec-h{margin-bottom:6px}
.srow{display:flex;gap:14px;align-items:center;padding:14px 4px;border-bottom:1px solid var(--line);text-decoration:none;color:var(--ink);min-height:56px}
.srow:hover{background:#fafaf8}.srow .t{flex:1;min-width:0}.srow .t b{display:block;font-size:15px}.srow .t span{font-size:14px;color:var(--ink2)}
mark{background:#ffe98a;color:inherit;padding:0 1px;border-radius:2px}
.empty{border:1.5px dashed #d6e1e9;border-radius:14px;padding:36px 28px;text-align:center;margin-top:24px}
.empty h2{font-size:20px;margin:0 0 6px}.empty p{color:var(--ink2);margin:0 0 16px}
/* form */
.fgrid{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:40px;margin-top:24px;align-items:start}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:20px}
.field label,.field legend{font-size:15px;font-weight:700}
.field .req{color:#b42318;margin-left:2px}
.field input,.field select,.field textarea{min-height:44px;border:1.5px solid #d6e1e9;border-radius:10px;padding:10px 12px;font:inherit;font-size:15px;background:#fff}
.field textarea{min-height:88px;resize:vertical}
.field .hint{font-size:13px;color:var(--ink2)}
.field .err{font-size:13px;color:#b42318;font-weight:700;display:none}
.field.bad input,.field.bad select,.field.bad textarea{border-color:#b42318}
.field.bad .err{display:block}
.row2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.fgrid>*,fieldset.field{min-width:0}
.solrow{display:grid;grid-template-columns:minmax(90px,130px) minmax(0,1fr) 44px;gap:8px;margin-bottom:8px}
.solrow button{min-height:44px;border:1px solid #d6e1e9;border-radius:10px;background:#fff;cursor:pointer}
.errsum{border:2px solid #b42318;border-radius:12px;padding:14px 18px;margin-bottom:20px;display:none}
.errsum.on{display:block}.errsum h2{font-size:15px;margin:0 0 6px;color:#b42318}.errsum a{color:#b42318}
.sticky-side{position:sticky;top:90px}
/* idea detail */
.track{display:flex;gap:0;list-style:none;padding:0;margin:18px 0 0;flex-wrap:wrap}
.track li{flex:1;min-width:110px;padding:10px 12px 10px 0;font-size:14px;color:var(--ink2);border-top:3px solid var(--line)}
.track li.done{border-color:var(--brand);color:var(--ink)}.track li.now{border-color:var(--brand);color:var(--ink);font-weight:700}
.bignote{background:#f6f1c8;border-radius:4px;padding:26px 26px 22px;font-size:20px;font-weight:700;line-height:1.45;box-shadow:0 2px 0 rgba(0,0,0,.06);max-width:560px}
.cmt{list-style:none;margin:0;padding:0}.cmt li{padding:12px 0;border-bottom:1px solid var(--line);font-size:15px}.cmt li b{margin-right:6px}.cmt li small{color:var(--ink2)}
/* me */
.todo li{display:flex;gap:12px;align-items:center;padding:14px 4px;border-bottom:1px solid var(--line)}
.todo .dot{width:8px;height:8px;border-radius:50%;background:#b42318;flex:none}
.todo .t{flex:1}.todo .t b{display:block;font-size:15px}.todo .t span{font-size:14px;color:var(--ink2)}
.resbar{display:flex;justify-content:space-between;align-items:center;margin:0 0 12px;font-size:14px;color:var(--ink2)}
.resbar button{background:none;border:0;text-decoration:underline;cursor:pointer;font:inherit;color:var(--ink);min-height:36px}
.sticky [data-like],.sticky [data-freeze]{min-height:36px}
.sticky .open{color:inherit;text-decoration:none}.sticky .open:hover b{text-decoration:underline}
@media(max-width:900px){.dgrid,.fgrid{grid-template-columns:1fr}.sticky-side{position:static}.row2{grid-template-columns:1fr}.dh2 h1{font-size:24px}}

/* engagement: challenge, awards, badges */
.chal{display:grid;grid-template-columns:1.1fr 1fr;gap:20px;margin-top:40px}
.chal-card{border:2px solid var(--brand);border-radius:20px;padding:24px 26px;background:#fff;display:flex;flex-direction:column;gap:12px}
.chal-card .eyebrow{display:flex;gap:8px;align-items:center;font-size:13px;font-weight:700;color:var(--ink2)}
.chal-card h2{margin:0;font-size:24px;line-height:1.3}
.chal-card p{margin:0;color:#444;font-size:15px}
.x2{display:inline-block;background:var(--fillc);color:#fff;font-size:12px;font-weight:700;border-radius:999px;padding:2px 10px}
.meter{height:8px;background:var(--fill2);border-radius:99px;overflow:hidden}.meter i{display:block;height:100%;background:var(--fillc);border-radius:99px}
.meter-l{display:flex;justify-content:space-between;font-size:13px;color:var(--ink2);margin-bottom:6px}
.chal-act{display:flex;gap:8px;flex-wrap:wrap;margin-top:auto}
.aw-mini{border:1px solid #d6e1e9;border-radius:20px;padding:20px 22px;background:#fff}
.aw-mini h2{font-size:18px;margin:0 0 4px}.aw-mini .sub{font-size:13px;color:var(--ink2);margin:0 0 10px}
.aw-mini ul{list-style:none;margin:0;padding:0}
.aw-mini li{display:grid;grid-template-columns:84px 1fr auto;gap:10px;align-items:center;min-height:40px;border-top:1px solid var(--line);font-size:14px}
.aw-mini li b{font-size:13px}.aw-mini li em{font-style:normal;color:var(--ink2);font-size:13px}
.awgrid{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}
.aw{border:1px solid #d6e1e9;border-radius:16px;padding:18px;background:#fff;display:flex;flex-direction:column;gap:10px}
.aw h3{margin:0;font-size:16px}.aw .crit{font-size:13px;color:var(--ink2);margin:0;min-height:34px}
.aw ol{list-style:none;margin:0;padding:0;font-size:14px}
.aw ol li{display:flex;justify-content:space-between;gap:8px;padding:6px 0;border-top:1px solid var(--line)}
.aw ol li:first-child{font-weight:700;font-size:15px;border-top:2px solid var(--brand)}
.aw .rk{display:inline-block;width:20px;color:var(--ink2);font-weight:700}
.aw .mine{background:var(--fill);border-radius:8px;padding:8px 10px;font-size:13px}
.pts{width:100%;border-collapse:collapse;font-size:14px}.pts th,.pts td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line)}.pts th{background:var(--fill);font-size:13px;color:var(--ink2)}.pts td:last-child,.pts th:last-child{text-align:right;font-weight:700}
.badges{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;list-style:none;margin:0;padding:0}
.badge{border:1px solid #d6e1e9;border-radius:16px;padding:16px;display:flex;gap:14px;align-items:center;background:#fff}
.badge .bm{width:52px;height:52px;border-radius:50%;background:var(--fillc);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:13px;flex:none;text-align:center;line-height:1.1}
.badge.lock .bm{background:#fff;color:var(--ink3,#999);border:2px dashed #d6e1e9}
.badge b{display:block;font-size:15px}.badge span.c{font-size:13px;color:var(--ink2)}
.badge .meter{margin-top:6px;height:6px}
.badge.lock b{color:var(--ink2)}
.hof{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.hof li{background:var(--fill);border-radius:12px;padding:12px 14px;font-size:14px}.hof li b{display:block;font-size:15px;margin-top:2px}
.pastc{list-style:none;margin:0;padding:0}.pastc li{display:flex;gap:14px;align-items:center;min-height:52px;border-top:1px solid var(--line);font-size:15px}.pastc li span{color:var(--ink2);font-size:13px;width:60px;flex:none}
.myscore{display:grid;grid-template-columns:200px 1fr;gap:24px;align-items:center}
.myscore .big{font-size:40px;font-weight:800;line-height:1}.myscore .big small{font-size:14px;font-weight:400;color:var(--ink2);display:block;margin-top:6px}
.bdots{display:flex;gap:8px;flex-wrap:wrap}.bdots span{width:40px;height:40px;border-radius:50%;background:var(--fillc);color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center}.bdots span.lock{background:#fff;border:2px dashed #d6e1e9;color:#aaa}
.note-light{font-size:13px;color:var(--ink2);margin-top:10px}
@media(max-width:1100px){.awgrid{grid-template-columns:repeat(3,1fr)}.hof{grid-template-columns:repeat(3,1fr)}}
@media(max-width:900px){.chal{grid-template-columns:1fr}.awgrid{grid-template-columns:1fr 1fr}.badges{grid-template-columns:1fr 1fr}.hof{grid-template-columns:1fr 1fr}.myscore{grid-template-columns:1fr}}
@media(max-width:560px){.awgrid,.badges{grid-template-columns:1fr}.aw .crit{min-height:0}.aw-mini li{grid-template-columns:72px 1fr auto}}
.live{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--fillc);margin-right:6px;vertical-align:1px;animation:pulse 1.6s ease-in-out infinite}@keyframes pulse{50%{opacity:.25}}@media(prefers-reduced-motion:reduce){.live{animation:none}}
.util a{display:inline-flex;align-items:center;gap:5px}.gnav a{gap:6px}
@media (max-width:1100px){.util .ni{display:none}}
@media (max-width:700px){.gnav .ni{display:none}}

/* nav separators + Maker Lab as distinct action */
.gnav a{padding:0 14px}
.gnav a:not(.mk)+a:not(.mk)::before{content:"";position:absolute;left:0;top:50%;width:1px;height:14px;margin-top:-7px;background:var(--line)}
.gnav a[aria-current=page]::after{left:14px;right:14px}
.gnav a.mk{height:30px;align-self:center;margin-left:12px;padding:0 10px;gap:5px;border:1.5px solid var(--brand);border-radius:7px;color:var(--ink);font-weight:700}
.gnav a.mk:hover{background:var(--fill)}
.gnav a.mk[aria-current=page]{background:var(--fillc);color:#fff}
.gnav a.mk[aria-current=page]::after{display:none}
@media (max-width:1100px){.gnav a{padding:0 9px}.gnav a[aria-current=page]::after{left:9px;right:9px}.gnav a.mk{margin-left:8px;padding:0 8px}}
@media (max-width:820px){.gnav a{padding:0 6px}.gnav a[aria-current=page]::after{left:6px;right:6px}.gnav a.mk{margin-left:6px;padding:0 7px;height:28px}}

/* Idea Board option 3: wall + side rail */
.ib{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:36px;align-items:start;margin-bottom:56px}
.ib-main{min-width:0}
.ib .wall{margin-bottom:26px}
.ib-side{position:sticky;top:84px;display:flex;flex-direction:column;gap:22px}
.ib-side section{border:1px solid #d6e1e9;border-radius:16px;padding:16px 18px;background:#fff}
.ib-side h2{font-size:16px;margin:0 0 6px}
.mini-list{list-style:none;margin:0;padding:0}
.mini-list li{border-top:1px solid var(--line);padding:10px 0;font-size:13px;color:var(--ink2)}
.mini-list li:first-child{border-top:0}
.mini-list b{display:block;font-size:14px;color:var(--ink)}
.mini-list a{color:inherit;text-decoration:none;display:block}.mini-list a:hover b{text-decoration:underline}
.side-more{display:block;font-size:13px;margin-top:6px;color:var(--ink2)}
.sticky .ntop{display:flex;justify-content:space-between;font-size:12px;font-weight:700;color:var(--ink2);margin-top:4px}
.sticky .ntop.nready{color:var(--ink)}
.sticky .ntop.nready span:first-child{background:var(--fillc);color:#fff;border-radius:4px;padding:1px 7px}
.sticky.is-ready{outline:2px solid var(--brand);outline-offset:-2px}
.sticky .gauge{margin-bottom:4px}
.fr-link{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:13px;color:var(--ink2);margin-bottom:16px}
#frBox .fridge{margin-bottom:0}
@media(max-width:1000px){.ib{grid-template-columns:1fr}.ib-side{position:static;display:grid;grid-template-columns:1fr 1fr}}
@media(max-width:600px){.ib-side{grid-template-columns:1fr}}

/* Skill Store: same card frame as Agent Store, Skill accents */
.skcard{min-width:0}.skcard .ft>span:first-child{white-space:nowrap;flex:none}.skcard .ft{gap:10px}
.skcard .skt{display:flex;justify-content:flex-start;align-items:center;margin-bottom:-2px}
.skm{background:#fff;border:1.5px solid var(--brand);color:var(--ink)}
.skv{font-size:12px;color:var(--ink2)}
.skfile{font-size:13px;color:var(--ink2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}.skfile::before{content:"파일 · ";font-weight:700}
.skq{background:var(--fill);border-radius:10px;padding:10px 12px;border-left:3px solid var(--brand)}
.skql{display:block;font-size:11px;font-weight:700;color:var(--ink2);margin-bottom:4px}
.skq p{margin:0;font-size:13px;line-height:1.6;color:#333;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;min-height:calc(1.6em*4)}

/* idea steps (no activation threshold) */
.sticky .ntop2{display:flex;align-items:flex-start;gap:10px;margin:4px 0 6px}.sticky .nlike{font-size:12px;font-weight:700;white-space:nowrap}
.sticky .nstep{flex:1;list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr);gap:3px}
.sticky .nstep li{font-size:11px;color:var(--ink2);border-top:4px solid rgba(0,0,0,.1);padding-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sticky .nstep li.on{border-color:var(--brand)}
.sticky .nstep li.cur{color:var(--ink);font-weight:700}
.sticky.is-making{outline:2px solid var(--brand);outline-offset:-2px}
.sticky .mkby{font-size:12px;font-weight:700}

/* notification side panel */
.npanel{width:min(400px,100%);z-index:41;box-shadow:-12px 0 30px rgba(0,0,0,.08)}
#nScrim{z-index:40;background:rgba(0,0,0,.18)}
.npanel .dh{gap:6px}.npanel .dh b{display:flex;align-items:center;gap:8px;font-size:18px}
.npanel .nread{font-size:13px!important;width:auto!important;padding:0 10px;color:var(--ink2);text-decoration:underline}
.ntabs{display:flex;gap:6px;padding:12px 18px;border-bottom:1px solid var(--line)}
.ntabs button{height:32px;padding:0 12px;border:1px solid #d6e1e9;border-radius:999px;background:#fff;font-size:13px;cursor:pointer}
.ntabs button[aria-selected=true]{background:var(--fillc);color:#fff;border-color:var(--brand)}
.nbody{flex:1;overflow-y:auto;padding:4px 18px 18px}
.ngrp{font-size:12px;font-weight:700;color:var(--ink2);margin:16px 0 6px}
.nlist{list-style:none;margin:0;padding:0}
.nlist li{display:flex;gap:10px;padding:12px 0;border-top:1px solid var(--line)}
.nlist li:first-child{border-top:0}
.nlist .ndot{width:8px;height:8px;border-radius:50%;margin-top:7px;flex:none;background:transparent}
.nlist li.unread .ndot{background:var(--fillc)}
.nlist li div{display:flex;flex-direction:column;gap:3px;min-width:0}
.nlist li b{font-size:14px;line-height:1.4;font-weight:500}.nlist li.unread b{font-weight:700}
.nlist li span{font-size:13px;color:var(--ink2)}
.nlist li .btn{align-self:flex-start;margin-top:6px}
.nfoot{border-top:1px solid var(--line);padding:14px 18px;font-size:14px}
@media(prefers-reduced-motion:reduce){.drawer{transition:none}}

.drop{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-height:120px;border:2px dashed #d6e1e9;border-radius:12px;background:var(--fill);cursor:pointer;text-align:center;padding:16px}
.drop b{font-size:15px}.drop span{font-size:13px;color:var(--ink2)}
.drop:hover,.drop.over{border-color:var(--brand)}.drop.has{border-style:solid;border-color:var(--brand);background:#fff}
.field.bad .drop{border-color:#b42318}
.chkrow{display:flex;gap:8px 16px;flex-wrap:wrap}.chkrow label{display:flex;align-items:center;gap:6px;font-weight:400;font-size:15px;min-height:36px}

.fmore summary{cursor:pointer;font-size:13px;color:var(--ink2);text-decoration:underline;min-height:32px;display:flex;align-items:center;list-style:none}
.fmore summary::-webkit-details-marker{display:none}
.fmore[open] summary{display:none}

/* upload modals */
#addSol{align-self:flex-start}
.modal{position:fixed;inset:0;z-index:50;background:rgba(0,0,0,.4);display:none;align-items:flex-start;justify-content:center;padding:40px 16px;overflow-y:auto}
.modal.on{display:flex}
body.mopen{overflow:hidden}
.mbox{background:#fff;border-radius:18px;width:min(980px,100%);box-shadow:0 20px 60px rgba(0,0,0,.25);display:flex;flex-direction:column;max-height:calc(100vh - 80px)}
.mhead{display:flex;align-items:flex-start;gap:16px;padding:22px 26px 16px;border-bottom:1px solid var(--line)}
.mhead>div{flex:1}.mhead h2{margin:0;font-size:20px}.mhead p{margin:4px 0 0;color:var(--ink2);font-size:14px}
.mclose{border:0;background:none;font-size:20px;width:40px;height:40px;border-radius:8px;cursor:pointer;flex:none}.mclose:hover{background:var(--fill)}
.mbody{overflow-y:auto;padding:4px 26px 24px}
.mbody .fgrid{margin-top:18px;grid-template-columns:minmax(0,1fr) 300px;gap:28px}
.mbody .sticky-side{position:sticky;top:0}
@media(max-width:900px){.mbody .fgrid{grid-template-columns:1fr}}
@media(max-width:600px){.modal{padding:0}.mbox{border-radius:0;max-height:100vh;min-height:100vh}.mhead,.mbody{padding-left:16px;padding-right:16px}}

/* idea flow guide, builders, page search */
.iflow{list-style:none;margin:0 0 18px;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));counter-reset:f}
.iflow li{position:relative;padding:10px 14px 10px 40px;border:1px solid #d6e1e9;background:#fff;display:flex;flex-direction:column;gap:1px;min-width:0}
.iflow li+li{border-left:0}.iflow li:first-child{border-radius:10px 0 0 10px}.iflow li:last-child{border-radius:0 10px 10px 0}
.iflow li::before{counter-increment:f;content:counter(f);position:absolute;left:12px;top:12px;width:20px;height:20px;border-radius:50%;background:var(--fillc);color:#fff;font-size:12px;font-weight:700;display:grid;place-items:center}
.iflow b{font-size:14px}.iflow span{font-size:13px;color:var(--ink2)}
.ntop2{justify-content:space-between;align-items:center}
.avs{display:inline-flex}.avs i{font-style:normal;width:20px;height:20px;border-radius:50%;background:var(--fillc);color:#fff;font-size:11px;font-weight:700;display:grid;place-items:center;border:1.5px solid #fff}.avs i+i{margin-left:-6px}
.nmk{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:700}
