.b3-x{font-size:12px;font-weight:800;color:var(--pri)}
.b3-meta2{margin:6px 0 0;font-size:13px;font-weight:700;color:var(--ink3)}
.b3-nextg{margin-top:14px;padding-top:14px;border-top:1px solid var(--hair);width:100%}
/* ==== 시안 style 블록 7 ==== */
/* 11/18 전체 배지를 받는 방식 세 묶음으로 */
.b4-k{padding-top:28px}
.b4-k+.b4-k{margin-top:12px;border-top:1px solid var(--hair2)}
.b4-k h3{display:flex;align-items:baseline;gap:10px;margin:0;font-size:17px;font-weight:800;letter-spacing:-.3px;color:var(--brand-900)}
.b4-k h3 span{font-size:13px;font-weight:700;color:var(--ink3);font-variant-numeric:tabular-nums}
.b4-k p{margin:4px 0 0;font-size:13px;color:var(--ink3)}
.b4-k .b3-all{padding-top:16px}
.b9a-row{display:grid;grid-template-columns:132px minmax(0,1fr);gap:0 24px;align-items:start;padding:18px 0;border-top:1px solid var(--hair2)}
.b4-k p+.b9a-row{margin-top:16px}
