.b5-sw button[aria-pressed="true"]{color:#004772;border-color:#004772}.b5-sw button[aria-pressed="true"] b{color:#004772}
.b5-sw button:focus-visible{outline:2px solid #004772;outline-offset:3px}
.b5-bar{display:block;height:6px;border-radius:3px;background:var(--hair2);overflow:hidden}
