/* D 진행 목록 */
.b5-d{list-style:none;margin:0;padding:0}
.b5-d li{border-bottom:1px solid var(--hair)}
.b5-d button{all:unset;box-sizing:border-box;cursor:pointer;width:100%;display:grid;grid-template-columns:52px minmax(140px,220px) minmax(0,1fr) 200px;gap:6px 22px;align-items:center;padding:14px 4px}
