.b5-t b{display:block;font-size:15px;font-weight:800;color:var(--brand-900)}
.b5-t small{display:block;font-size:12px;font-weight:700}
.b5-st{font-size:13px;color:var(--ink2)}.b5-st b{color:var(--ink)}
.b5-p{display:flex;align-items:center;gap:10px}.b5-p .b5-bar{flex:1}
