#notifPanel .nx-cnt{display:inline-grid;place-items:center;min-width:24px;height:24px;padding:0 6px;border-radius:999px;border:1px solid var(--hair2);font-size:13px;font-weight:700;color:var(--ink);background:transparent}
#notifPanel .nx-tl{all:unset;cursor:pointer;font-size:13px;color:var(--ink2);text-decoration:underline;text-underline-offset:4px;text-decoration-color:var(--hair2)}
