#notifPanel .nx-list{list-style:none;margin:0;padding:0}
#notifPanel .nx-list li{display:grid;grid-template-columns:8px minmax(0,1fr) 28px;gap:12px;align-items:start;padding:10px 12px 10px 22px;transition:background .15s}
#notifPanel .nx-list li:hover{background:rgba(0,71,114,.04)}
#notifPanel .nx-dot{width:7px;height:7px;border-radius:50%;margin-top:7px;background:transparent}
#notifPanel li.unread .nx-dot{background:var(--ink)}
#notifPanel .nx-go{display:grid;gap:3px;color:inherit;text-decoration:none;min-width:0}
