#notifPanel .nx-foot a:hover{text-decoration-color:currentColor}
/* ==== 시안 style 블록 10 ==== */
/* 11/18 버튼·검색창 = B안 변주 1 '화살표 원' (b6-). 주 버튼만 채움, 이동하는 주 버튼엔 오른쪽 흰 원+화살표, 보조는 밑줄 글자, 자세히는 글자+화살표, 검색은 둥근 돋보기 버튼 */
#notifPanel [hidden]{display:none!important}
.btn.pri{background:#004772!important;background-image:none!important;color:#fff!important;border:0!important;box-shadow:none!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important;border-radius:999px!important;height:40px!important;min-height:0!important;padding:0 20px!important;font-size:14px!important;font-weight:600!important;gap:8px;transform:none!important}
.btn.pri:hover{background:#003f6d!important}
.btn.pri.sm{height:32px!important;padding:0 14px!important;font-size:13px!important}
.btn.pri[disabled]{background:#f3f6f8!important;color:#8c8c8c!important;cursor:not-allowed}
.btn.pri.b6-go{padding:0 5px 0 20px!important;gap:12px}
.btn.pri.sm.b6-go{padding:0 4px 0 14px!important;gap:8px}
.btn.b6-go::after,.btn.b6-more::after{content:none!important}
.b6-pk{flex:none;width:30px;height:30px;border-radius:50%;background:#fff;color:#004772;display:grid;place-items:center;transition:transform .2s}
.btn.sm .b6-pk{width:24px;height:24px}
.b6-pk svg,.b6-sbtn svg{width:14px;height:14px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.btn.b6-go:hover .b6-pk,.btn.b6-go:focus-visible .b6-pk{transform:translateX(3px) rotate(-45deg)}
.btn:not(.pri):not(.b6-keep){background:none!important;border:0!important;box-shadow:none!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important;height:auto!important;min-height:0!important;padding:6px 2px!important;border-radius:2px!important;color:var(--brand,#004772)!important;font-size:14px!important;font-weight:600!important;text-decoration:underline;text-decoration-color:rgba(0,71,114,.3);text-underline-offset:5px;text-decoration-thickness:1px;transform:none!important}
.btn:not(.pri):not(.b6-keep):hover{color:#004772!important;text-decoration-color:#004772}
.btn.sm:not(.pri):not(.b6-keep){font-size:13px!important}
.btn.b6-more:not(.pri){text-decoration:none!important;color:#004772!important}
.b6-ar{display:inline-block;margin-left:2px;transition:transform .18s}
.btn.b6-more:hover .b6-ar{transform:translateX(3px)}
.btn:focus-visible{outline:2px solid #004772!important;outline-offset:2px}
.b4-btn.b6-sbtn{padding:0!important;aspect-ratio:1;width:auto;min-width:30px;border-radius:50%!important;gap:0}
.b4-btn.b6-sbtn svg{width:18px!important;height:18px!important;transition:transform .2s}
.b4-btn.b6-sbtn:hover svg{transform:rotate(-12deg) scale(1.08)}
form[role=search] .btn.pri.b6-sbtn{width:44px!important;height:44px!important;padding:0!important;border-radius:50%!important;flex:none}
form[role=search] .btn.pri.b6-sbtn svg{width:18px;height:18px;transition:transform .2s}
form[role=search] .btn.pri.b6-sbtn:hover svg{transform:rotate(-12deg) scale(1.08)}
/* 홈은 버튼 대신 글자 링크(희재 11/18) */
#home .btn.b6-home{background:none!important;color:#004772!important;height:auto!important;padding:4px 0!important;border-radius:2px!important;font-size:15px!important;font-weight:700!important;gap:6px}
#home .btn.b6-home:hover{background:none!important;color:#003f6d!important}
#home .btn.b6-home:hover .b6-ar{transform:translateX(3px)}
#home .btn:not(.pri).b6-more{font-size:15px!important;font-weight:700!important}
/* 검색창 등장: 가운데 원에서 양옆으로 펼쳐짐 */
