.zbox{position:relative;overflow:hidden;isolation:isolate;background:radial-gradient(420px circle at var(--mx,-999px) var(--my,-999px),rgba(0,71,114,.14),transparent 50%),radial-gradient(60% 70% at 100% 0%,rgba(143,188,218,.35),transparent 70%),linear-gradient(160deg,#f6fafd,#eaf2f8)}
.zbox{counter-increment:zs}
.zbox::after{content:"0" counter(zs);position:absolute;right:-6px;bottom:-34px;z-index:-1;font-size:150px;font-weight:900;letter-spacing:-6px;line-height:1;color:transparent;-webkit-text-stroke:1.5px rgba(0,71,114,.12);pointer-events:none}
@supports (animation-timeline:view()){@media (prefers-reduced-motion:no-preference){.zbox::after{animation:drift linear both;animation-timeline:view()}}}
@keyframes drift{from{transform:translateY(40px)}to{transform:translateY(-40px)}}
.zrow:nth-child(4){background:none}
/* 마지막 단계(만들고 배포하기)를 밤하늘 카드로 */
.zig .zrow:last-child .zbox{background:radial-gradient(420px circle at var(--mx,-999px) var(--my,-999px),rgba(0,71,114,.22),transparent 50%),linear-gradient(162deg,transparent 40%,rgba(0,71,114,.28) 58%,rgba(255,255,255,.35) 60%,rgba(169,180,255,.25) 62%,transparent 75%),linear-gradient(180deg,#00121f,#002a45);color:#fff;box-shadow:0 30px 60px -30px rgba(0,18,31,.6)}
.zig .zrow:last-child .zbox h3{color:#fff}.zig .zrow:last-child .zbox p{color:rgba(220,236,248,.75)}
.zig .zrow:last-child .zbox::after{-webkit-text-stroke-color:rgba(255,255,255,.12)}
.zig .zrow:last-child .zbox .btn:not(.pri){background:rgba(255,255,255,.06);color:#fff;border-color:rgba(255,255,255,.4)}
.zig .zrow:last-child .zbox .btn.pri{background:#fff;color:var(--brand-900);border-color:#fff}
.zig .zrow:last-child .zbox .zn{background:#fff;color:var(--brand)}
.zfacts li,.zcase{background:radial-gradient(300px circle at var(--mx,-999px) var(--my,-999px),rgba(0,71,114,.10),transparent 50%),#fff}

/* 스크롤 등장 */
.rv{opacity:0;transform:translateY(28px);transition:opacity .8s var(--ease) var(--d,0ms),transform .9s var(--ease) var(--d,0ms)}
.rv.in{opacity:1;transform:none}
.zrow.rv{transform:translateY(40px)}
.bwall li.rv{transform:translateY(24px) scale(.92)}
.rv.in.card:hover,.rv.in.mk-card:hover{transform:translateY(-3px)}
#home .zrow,#home .zig>h2,.page.on .ct-row{animation:none}

/* 카드 마우스 빛 */
.card,.mk-card{background:radial-gradient(420px circle at var(--mx,-999px) var(--my,-999px),rgba(0,71,114,.10),transparent 45%),#fff}
