.ptop::before{content:"";position:absolute;z-index:-1;top:0;bottom:0;left:-100vmax;right:-100vmax;height:auto;pointer-events:none;
  background:linear-gradient(162deg,transparent 48%,rgba(0,71,114,.22) 58%,rgba(255,255,255,.28) 60%,rgba(169,180,255,.18) 62%,transparent 72%),radial-gradient(40% 140% at 78% 120%,rgba(0,71,114,.55),transparent 70%),linear-gradient(180deg,#00121f,#001f35);background-size:200% 100%,100% 100%,100% 100%;animation:sweep 14s ease-in-out infinite alternate}
