#home .hero h1 .hl{background:linear-gradient(90deg,#004772 0%,#004772 25%,#2fa3d9 45%,#5b7cf0 60%,#004772 80%,#004772 100%);background-size:220% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:shimmer 7s linear infinite;padding-bottom:.06em}
#home .hero .search label{background:rgba(255,255,255,.82);border:1.5px solid rgba(0,71,114,.35);-webkit-backdrop-filter:blur(16px) saturate(1.4);backdrop-filter:blur(16px) saturate(1.4);box-shadow:0 1px 0 #fff inset,0 18px 40px -18px rgba(0,37,60,.35)}
