/* ===== 11/18 v8: 홈 디자인을 전체 화면에 통일 ===== */
:root{--glow-core:#8fd5f1;--glow-rim:#d2daff;--hair:rgba(0,71,114,.12);--hair2:rgba(0,71,114,.2);--glass:rgba(255,255,255,.72);--glass-b:rgba(255,255,255,.9);--sh-glass:0 24px 60px -30px rgba(0,37,60,.35)}

/* ---------- 1) 파란 버튼 글라스 효과 ---------- */
.btn.pri,#home .hero .search .btn.pri,.cattabs:not(.mp-seg) a[aria-current=page],.chip[aria-pressed=true]{
  background-color:rgba(0,71,114,.9);
  background-image:linear-gradient(180deg,rgba(255,255,255,.22) 0%,rgba(255,255,255,0) 62%),linear-gradient(115deg,transparent 35%,rgba(255,255,255,.34) 50%,transparent 65%);
  background-size:100% 100%,260% 100%;background-position:0 0,130% 0;background-repeat:no-repeat;
  -webkit-backdrop-filter:blur(12px) saturate(1.6);backdrop-filter:blur(12px) saturate(1.6);
  border:1px solid rgba(255,255,255,.3);color:#fff;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.42),0 6px 18px -10px rgba(0,71,114,.6);
  transition:background-position .7s var(--ease),background-color .25s,box-shadow .25s,transform .25s var(--ease)}
.btn.pri:hover,#home .hero .search .btn.pri:hover,.chip[aria-pressed=true]:hover{background-color:rgba(0,63,109,.88);background-position:0 0,-30% 0;border-color:rgba(255,255,255,.45);box-shadow:inset 0 1px 0 rgba(255,255,255,.5),inset 0 -1px 0 rgba(0,37,60,.14),0 12px 26px -12px rgba(0,71,114,.7);transform:translateY(-1px)}
.btn.pri:active{transform:translateY(0) scale(.98)}
.cattabs:not(.mp-seg) a[aria-current=page] span{color:#fff}

/* ---------- 2) 목록 화면 머리: 남색 띠 → 홈과 같은 하늘색 그릇 빛 ---------- */
.ptop{color:var(--ink);border-bottom-color:transparent;padding-top:56px;padding-bottom:40px}
.ptop.mp{padding-top:56px}
.ptop::before{top:-140px;bottom:-80px;left:-100vmax;right:-100vmax;animation:glowBreath 10s ease-in-out infinite alternate;
  background:radial-gradient(46% 100% at 50% 0%,var(--glow-core) 0%,#9ad8f2 34%,rgba(201,214,255,.85) 64%,rgba(255,255,255,0) 100%)}
@keyframes glowBreath{from{transform:scaleX(1)}to{transform:scaleX(1.12)}}
@media(prefers-reduced-motion:reduce){.ptop::before{animation:none}}
.ptop h1{background:none;-webkit-background-clip:border-box;background-clip:border-box;color:var(--brand-900);animation:none;font-size:40px;font-weight:800;letter-spacing:-1.4px}
.ptop p{color:var(--ink2);font-size:16px}
.ptop .k{color:var(--pri)}
