.ptop .btn:not(.pri):hover{background:#fff;border-color:rgba(0,71,114,.4);box-shadow:0 8px 20px -14px rgba(0,37,60,.4)}
@media(max-width:820px){.ptop{padding-top:36px;padding-bottom:28px}.ptop h1{font-size:30px}}
/* 페이지 들어올 때 제목·설명 차례로 */
@media (prefers-reduced-motion:no-preference){
  .page.on .ptop h1,.page.on .ptop p,.page.on .ptop .k,.page.on .ptop .btn,.page.on .dh2 h1,.page.on .dh2 p{animation:upIn .8s var(--ease) both}
  .page.on .ptop p,.page.on .dh2 p{animation-delay:.08s}
  .page.on .ptop .btn{animation-delay:.16s}
  .page.on{animation:pageIn .45s ease both}
}
@keyframes upIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
