/* 2단계 아이디어: 포스트잇 → 색 점 + 선 목록 */
#home .znotes{display:block;border-top:1px solid var(--hair2);border-bottom:1px solid var(--hair)}
#home .znote,#home .znote:hover,#home .znote.n1,#home .znote.n2,#home .znote.n3,#home .znote.rv.in,#home .zrow.rev .znote.rv.in{display:grid;grid-template-columns:12px minmax(0,1fr) auto;grid-template-rows:auto auto;column-gap:14px;row-gap:2px;align-items:center;min-height:0;padding:16px 0;background:none;box-shadow:none;transform:none;border-top:1px solid var(--hair)}
#home .znote:first-child{border-top:0}
#home .znote::before{position:static;grid-row:1/3;width:12px;height:12px;margin:0;border-radius:3px;background:#f3df8a;transform:rotate(-6deg)}
#home .znote.n2::before{background:#a9d8b4}#home .znote.n3::before{background:#f2b9a2}
#home .znote>a{grid-column:2;grid-row:1}
#home .znote b{font-size:16px;font-weight:700;color:var(--brand-900);transition:color .2s}
#home .znote:hover b{color:var(--pri)}
#home .znote>span{grid-column:2;grid-row:2;margin:0;font-size:13px}
#home .znote .zhand{grid-column:3;grid-row:1/3;height:34px;border:0;background:none;color:var(--pri);padding:0 4px}
#home .znote .zhand:hover{color:var(--pri-h)}
#home .znote .zhand[aria-pressed=true]{color:var(--brand-900)}
/* 3단계 고객 사례: 선 목록 */
#home .zcases{gap:0;border-top:1px solid var(--hair2);border-bottom:1px solid var(--hair)}
#home .zcase,#home .zcase:hover{grid-template-columns:150px minmax(0,1fr) auto;border:0;border-top:1px solid var(--hair);border-radius:0;padding:18px 0;background:none;box-shadow:none;transform:none}
#home .zcase:first-child{border-top:0}
#home .zcase .zci{display:flex;flex-direction:column;gap:2px;font-size:13px;color:var(--ink2)}
#home .zcase .zci .kchip{padding:0;background:none;font-size:12px;font-weight:700;color:var(--pri)}
#home .zcase b{font-size:16px;color:var(--brand-900);transition:color .2s}
#home .zcase:hover b{color:var(--pri)}
#home .zcase em{font-size:15px;font-weight:800;color:var(--brand-900)}
/* 4단계 만들기 흐름: 큰 번호 3칸 */
#home .zflow{gap:0}
#home .zflow li,#home .zflow li:hover{border:0;border-left:1px solid var(--hair);border-radius:0;background:none;box-shadow:none;transform:none;padding:2px 14px 2px 22px;gap:6px}
#home .zflow li:first-child{border-left:0;padding-left:0}
#home .zflow li+li::after{display:none}
#home .zflow li::before{content:"0" counter(zf);font-size:52px;font-weight:800;letter-spacing:-2px;line-height:1;color:rgba(0,71,114,.28);margin-bottom:10px}
#home .zflow b{font-size:17px;font-weight:800;color:var(--brand-900)}
#home .zflow span{font-size:13px;line-height:1.5;word-break:keep-all}
@media(max-width:900px){
  #home .zcase{grid-template-columns:1fr;gap:4px}
  #home .zflow{grid-template-columns:repeat(3,minmax(0,1fr))}
  #home .zflow li{padding:2px 8px 2px 12px}
  #home .zflow li::before{font-size:36px}
  #home .zflow b{font-size:15px}
}

/* ---------- 8) 모션 정리: 같은 속도·거리, 흐림 효과 없음 ---------- */
@media (prefers-reduced-motion:no-preference){
  .rv{filter:none!important}
  .page.on .card.rv,.page.on .mk-card.rv,.page.on .fboard.rv,.page.on .ct-row.rv,.page.on .sticky.rv,.page.on .rows li.rv,.page.on .sec-h.rv{opacity:0;transform:translateY(20px);transition:opacity .7s var(--ease) var(--d,0ms),transform .8s var(--ease) var(--d,0ms)}
  .page.on .card.rv.in,.page.on .mk-card.rv.in,.page.on .fboard.rv.in,.page.on .ct-row.rv.in,.page.on .rows li.rv.in,.page.on .sec-h.rv.in{opacity:1;transform:none}
  #home .znote.rv,#home .zrow.rev .znote.rv,#home .zcase.rv,#home .zrow.rev .zcase.rv,#home .zflow li.rv,#home .zrow.rev .zflow li.rv{opacity:0;transform:translateY(14px);transition:opacity .6s var(--ease) calc(var(--d) + .3s),transform .7s var(--ease) calc(var(--d) + .3s)}
  #home .znote.rv.in,#home .zcase.rv.in,#home .zflow li.rv.in,#home .zrow.rev .zcase.rv.in,#home .zrow.rev .zflow li.rv.in{opacity:1;transform:none}
  .card,.mk-card{transition:transform .35s var(--ease),box-shadow .35s var(--ease),opacity .7s var(--ease)}
}

/* 검색창 테두리 통일 (Case Library·Idea Board) */
.cf-search,.psearch,.ca-fbtn{border:1px solid rgba(0,71,114,.2)!important;background:rgba(255,255,255,.82);-webkit-backdrop-filter:blur(16px) saturate(1.4);backdrop-filter:blur(16px) saturate(1.4);box-shadow:0 12px 32px -20px rgba(0,37,60,.3)}
.cf-search:focus-within,.psearch:focus-within{border-color:var(--pri)!important;box-shadow:0 0 0 4px rgba(0,71,114,.12)}
.ca-fbtn{color:var(--brand)}
.scrim{-webkit-backdrop-filter:none!important;backdrop-filter:none!important;filter:none}
.mnav a{border:0!important}
.mnav a:hover{background:#fff;box-shadow:inset 0 0 0 1px rgba(0,71,114,.16)}
#home .zig .zrow .znote.rv.in,#home .zig .zrow.rev .znote.rv.in{opacity:1;transform:none}
#home .zig .zrow .znote,#home .zig .zrow.rev .znote{rotate:none}
#home .zcase,#home .zcase:hover{grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto;row-gap:6px;column-gap:16px;align-items:baseline;text-align:left}
#home .zcase .zci{grid-column:1/-1;flex-direction:row;align-items:center;justify-content:flex-start;gap:8px;text-align:left}
#home .zcase .zci .kchip{margin:0}
#home .zcase b{grid-column:1;grid-row:2}
#home .zcase em{grid-column:2;grid-row:2;text-align:right}
@media(max-width:900px){#home .zcase,#home .zcase:hover{grid-template-columns:1fr}#home .zcase em{grid-column:1;grid-row:3;text-align:left;color:var(--pri)}}
/* ==== 시안 style 블록 17 ==== */
/* ===== 11/18 개인 배지 (bdg- 접두사, 원본 클래스와 충돌 방지) ===== */
.bdg-em{display:block;flex:none}
.bdg-em svg{display:block;width:100%;height:100%;overflow:visible}

/* 배지 모음 화면 */
#badges .ptop{align-items:flex-end}
.bdg-sum{display:flex;align-items:flex-end;gap:28px}
.bdg-sum>div{display:flex;flex-direction:column;gap:2px}
.bdg-sum small{font-size:13px;color:var(--ink2)}
.bdg-big{font-size:40px;font-weight:800;letter-spacing:-1.2px;line-height:1;color:var(--brand-900)}
.bdg-big span{font-size:20px;font-weight:700;color:var(--ink3);letter-spacing:0;margin-left:4px}
.bdg-rep{flex-direction:row!important;align-items:center;gap:12px!important;padding-left:28px;border-left:1px solid var(--hair2)}
.bdg-rep b{display:block;font-size:16px;color:var(--brand-900)}
.bdg-rep button{border:0;background:none;padding:0;font:inherit;font-size:13px;font-weight:700;color:var(--pri);cursor:pointer}
.bdg-rep button:hover{color:var(--pri-h)}

.bdg-sec{margin-top:56px}
.bdg-sec>header{display:flex;align-items:baseline;gap:12px;padding-bottom:14px;border-bottom:1px solid var(--hair2)}
.bdg-sec>header h2{margin:0;font-size:20px;font-weight:800;color:var(--brand-900)}
.bdg-sec>header small{font-size:13px;color:var(--ink3)}

/* 곧 받을 배지: 3칸, 세로선 구분 */
.bdg-next ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,1fr)}
.bdg-next li+li{border-left:1px solid var(--hair)}
.bdg-next button{all:unset;box-sizing:border-box;cursor:pointer;display:grid;grid-template-columns:64px 1fr;gap:6px 16px;align-items:center;padding:22px 24px;width:100%}
.bdg-next li:first-child button{padding-left:0}
.bdg-next button:focus-visible{outline:3px solid var(--brand);outline-offset:-3px;border-radius:8px}
.bdg-next .bdg-em{width:64px;height:64px;grid-row:1/3}
.bdg-next b{font-size:16px;color:var(--ink)}
.bdg-next button:hover b{color:var(--pri)}
.bdg-next p{margin:0;font-size:13px;color:var(--ink2);line-height:1.5}
.bdg-next p em{font-style:normal;font-weight:700;color:var(--pri)}

/* 전체 배지 */
.bdg-tabs{display:flex;gap:20px;margin-left:auto}
.bdg-tabs button{border:0;background:none;padding:4px 0;font:inherit;font-size:14px;color:var(--ink3);cursor:pointer;position:relative}
.bdg-tabs button[aria-pressed=true]{color:var(--brand-900);font-weight:700}
.bdg-tabs button[aria-pressed=true]::after{content:"";position:absolute;left:0;right:0;bottom:-15px;height:2px;background:var(--pri)}
.bdg-grp{display:grid;grid-template-columns:250px 1fr;gap:24px;padding:28px 0;border-bottom:1px solid var(--hair)}
.bdg-grp[hidden]{display:none}
.bdg-gh h3{margin:0 0 4px;font-size:18px;font-weight:800;color:var(--brand-900);display:flex;align-items:center;gap:8px}
.bdg-gh h3 i{width:8px;height:8px;border-radius:50%;flex:none}
.bdg-gh p{margin:0 0 8px;font-size:13px;color:var(--ink2);line-height:1.5}
.bdg-gh small{font-size:12px;color:var(--ink3)}
.bdg-gh .bdg-opt{display:inline-block;font-size:11px;font-weight:700;color:var(--ink2);border:1px solid #d6e1e9;border-radius:999px;padding:0 8px;margin-left:2px}
.bdg-cells{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(136px,1fr));gap:8px 12px}
.bdg-cell{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;padding:8px 6px 10px;width:100%;border-radius:12px}
.bdg-cell:focus-visible{outline:3px solid var(--brand);outline-offset:0}
.bdg-cell .bdg-em{width:76px;height:76px;margin-bottom:6px;transition:transform .35s var(--ease)}
.bdg-cell:hover .bdg-em{transform:translateY(-4px)}
.bdg-cell b{font-size:14px;color:var(--ink);line-height:1.35}
.bdg-cell:hover b{color:var(--pri)}
.bdg-cell .bdg-c1{font-size:12px;color:var(--ink2);line-height:1.4}
.bdg-cell .bdg-c2{font-size:12px;color:var(--ink3)}
.bdg-cell.off b{color:var(--ink2)}
.bdg-rare{font-weight:700;margin-left:4px}

/* 상세 창 */
.bdg-scrim{position:fixed;inset:0;z-index:60;background:rgba(0,37,60,.28);opacity:0;pointer-events:none;transition:opacity .25s}
.bdg-scrim.on{opacity:1;pointer-events:auto}
.bdg-dlg{position:fixed;z-index:61;left:50%;top:50%;width:min(440px,calc(100% - 32px));max-height:calc(100vh - 48px);overflow:auto;transform:translate(-50%,calc(-50% + 18px));opacity:0;pointer-events:none;transition:opacity .3s,transform .45s var(--ease);
  background:var(--glass-b,rgba(255,255,255,.92));-webkit-backdrop-filter:blur(24px) saturate(1.5);backdrop-filter:blur(24px) saturate(1.5);border:1px solid rgba(255,255,255,.9);border-radius:20px;box-shadow:var(--sh-glass,0 24px 60px -30px rgba(0,37,60,.35));padding:28px 28px 24px}
.bdg-dlg.on{opacity:1;transform:translate(-50%,-50%);pointer-events:auto}
.bdg-x{position:absolute;right:14px;top:14px;width:36px;height:36px;border:0;background:none;border-radius:8px;font-size:16px;cursor:pointer;color:var(--ink2)}
.bdg-x:hover{background:var(--fill)}
.bdg-dtop{display:flex;flex-direction:column;align-items:center;text-align:center;gap:4px;padding-bottom:20px;border-bottom:1px solid var(--hair)}
.bdg-dtop .bdg-em{width:120px;height:120px;margin-bottom:10px}
.bdg-dtop .bdg-k{font-size:12px;font-weight:700;letter-spacing:.2px}
.bdg-dtop h2{margin:0;font-size:28px;font-weight:800;letter-spacing:-.8px;color:var(--brand-900)}
.bdg-dtop p{margin:2px 0 0;font-size:15px;color:var(--ink2)}
.bdg-drows{margin:0;padding:6px 0 0}
.bdg-drows>div{display:grid;grid-template-columns:84px 1fr;gap:12px;padding:12px 0;border-bottom:1px solid var(--hair);font-size:14px}
.bdg-drows dt{color:var(--ink3);font-size:13px;padding-top:1px}
.bdg-drows dd{margin:0;color:var(--ink)}
.bdg-bar{display:block;height:2px;background:var(--hair2);margin-top:8px;position:relative}
.bdg-bar i{position:absolute;left:0;top:0;bottom:0;background:var(--pri)}
.bdg-who{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}
.bdg-who span{width:24px;height:24px;border-radius:50%;background:var(--tint);color:var(--brand);font-size:11px;font-weight:700;display:grid;place-items:center}
.bdg-who span.me{background:var(--pri);color:#fff}
.bdg-dact{display:flex;gap:8px;justify-content:center;margin-top:20px;flex-wrap:wrap}

/* 받는 순간 */
.bdg-cele{position:fixed;z-index:62;left:50%;top:50%;width:min(400px,calc(100% - 32px));transform:translate(-50%,calc(-50% + 18px));opacity:0;pointer-events:none;transition:opacity .3s,transform .5s var(--ease);
  background:#fff;border-radius:20px;box-shadow:var(--sh-glass,0 24px 60px -30px rgba(0,37,60,.35));padding:36px 28px 24px;text-align:center;overflow:hidden}
.bdg-cele.on{opacity:1;transform:translate(-50%,-50%);pointer-events:auto}
.bdg-cele::before{content:"";position:absolute;inset:0;z-index:0;background:radial-gradient(70% 55% at 50% 22%,var(--glow-core,#8fd5f1) 0%,rgba(201,214,255,.6) 55%,rgba(255,255,255,0) 100%);opacity:.55}
.bdg-cele>*{position:relative;z-index:1}
.bdg-cele .bdg-k{font-size:13px;font-weight:700;color:var(--pri)}
.bdg-cele h2{margin:6px 0 4px;font-size:28px;font-weight:800;letter-spacing:-.8px;color:var(--brand-900)}
.bdg-cele p{margin:0;font-size:15px;color:var(--ink2)}
.bdg-stage{position:relative;width:140px;height:140px;margin:0 auto 18px}
.bdg-stage .bdg-em{position:absolute;left:10px;top:10px;width:120px;height:120px}
.bdg-rays{position:absolute;inset:-30px;width:200px;height:200px}
.bdg-rays line{stroke:var(--pri);stroke-width:2;stroke-linecap:round;opacity:0}
@media (prefers-reduced-motion:no-preference){
  .bdg-cele.on .bdg-stage .bdg-em{animation:bdgPop .7s var(--ease) both .1s}
  .bdg-cele.on .bdg-rays line{animation:bdgRay .9s var(--ease) both .45s}
  .bdg-cele.on h2,.bdg-cele.on p,.bdg-cele.on .bdg-k,.bdg-cele.on .bdg-dact{animation:upIn .7s var(--ease) both .35s}
  .bdg-cele.on p{animation-delay:.42s}.bdg-cele.on .bdg-dact{animation-delay:.5s}
  .bdg-rv{opacity:0;transform:translateY(16px);transition:opacity .6s var(--ease) var(--d,0ms),transform .7s var(--ease) var(--d,0ms)}
  .bdg-rv.bdg-in{opacity:1;transform:none}
}
@keyframes bdgPop{0%{opacity:0;transform:translateY(16px) scale(.9)}100%{opacity:1;transform:none}}
@keyframes bdgRay{0%{opacity:0;stroke-dashoffset:10}40%{opacity:1}100%{opacity:0;stroke-dashoffset:-10}}

/* 프로필 패널 '내 배지' */
.medrawer .mdh .bdg-em{width:22px;height:22px}
.medrawer .mdh .bdg-nm{display:flex;align-items:center;gap:6px;flex:1;min-width:0}
.medrawer .mdh .bdg-nm b{flex:none}
.bdg-mine-h{display:flex;align-items:baseline;justify-content:space-between}
.bdg-mine-h small{font-size:13px;color:var(--ink3)}
.bdg-mine-h small b{font-size:16px;color:var(--brand-900);display:inline}
.bdg-shelf{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:12px 8px}
.bdg-shelf a{display:flex;flex-direction:column;align-items:center;gap:4px;text-decoration:none;text-align:center}
.bdg-shelf .bdg-em{width:48px;height:48px;transition:transform .3s var(--ease)}
.bdg-shelf a:hover .bdg-em{transform:translateY(-3px)}
.bdg-shelf small{font-size:11px;color:var(--ink2);line-height:1.3}
.bdg-soon{display:grid;grid-template-columns:40px 1fr;gap:2px 12px;align-items:center;padding:14px 0 0;margin-top:14px;border-top:1px solid var(--hair)}
.bdg-soon .bdg-em{width:40px;height:40px;grid-row:1/3}
.bdg-soon b{font-size:14px}
.bdg-soon small{font-size:12px;color:var(--ink2)}
.bdg-soon small em{font-style:normal;font-weight:700;color:var(--pri)}
.bdg-more{display:inline-block;margin-top:14px;font-size:14px;font-weight:700;color:var(--pri);text-decoration:none}
.bdg-more:hover{color:var(--pri-h)}

/* 설계 메모 (시안 설명) */
.bdg-memo{margin-top:88px;padding-top:40px;border-top:2px solid var(--brand-900)}
.bdg-memo-k{display:inline-block;font-size:12px;font-weight:700;color:#fff;background:var(--brand-900);border-radius:999px;padding:2px 10px}
.bdg-memo>h2{margin:10px 0 4px;font-size:24px;font-weight:800;letter-spacing:-.6px;color:var(--brand-900)}
.bdg-memo>p{margin:0;color:var(--ink2)}
.bdg-memo h3{margin:44px 0 0;font-size:20px;font-weight:800;color:var(--brand-900);padding-bottom:14px;border-bottom:1px solid var(--hair2)}
.bdg-pr{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(5,1fr)}
.bdg-pr li{padding:20px 18px 4px 0}
.bdg-pr li+li{padding-left:18px;border-left:1px solid var(--hair)}
.bdg-pr em{display:block;font-style:normal;font-size:40px;font-weight:800;letter-spacing:-1px;line-height:1;color:var(--tint2,#e6edf1)}
.bdg-pr b{display:block;margin:10px 0 6px;font-size:16px;color:var(--brand-900)}
.bdg-pr p{margin:0;font-size:13px;color:var(--ink2);line-height:1.6}
.bdg-where{list-style:none;margin:0;padding:0}
.bdg-where>li{display:grid;grid-template-columns:200px 1fr 300px;gap:24px;align-items:center;padding:22px 0;border-bottom:1px solid var(--hair)}
.bdg-where h4{margin:0;font-size:16px;color:var(--ink)}
.bdg-where .bdg-st{display:inline-block;margin-top:4px;font-size:12px;font-weight:700}
.bdg-where .bdg-st.y{color:var(--pri)}.bdg-where .bdg-st.n{color:var(--ink3)}
.bdg-where p{margin:0;font-size:14px;color:var(--ink2)}
.bdg-mock{font-size:13px}
.bdg-mock .bdg-cm{display:grid;grid-template-columns:30px 1fr;gap:2px 10px;align-items:center}
.bdg-mock .bdg-cm .av{grid-row:1/3;display:grid;place-items:center;background:var(--tint);color:var(--brand);font-weight:700;font-size:12px}
.bdg-mock .bdg-cm span.n{display:flex;align-items:center;gap:5px;font-size:13px}
.bdg-mock .bdg-cm span.n .bdg-em{width:18px;height:18px}
.bdg-mock .bdg-cm span.n small{color:var(--ink3);font-size:12px;margin-left:4px}
.bdg-mock .bdg-cm p{margin:0;font-size:13px;color:var(--ink)}
.bdg-mock .bdg-nt{display:grid;grid-template-columns:8px 1fr;gap:2px 10px}
.bdg-mock .bdg-nt i{width:8px;height:8px;border-radius:50%;background:var(--pri);margin-top:7px;box-shadow:0 0 0 4px rgba(0,71,114,.14)}
.bdg-mock .bdg-nt b{font-size:13px}.bdg-mock .bdg-nt small{grid-column:2;font-size:12px;color:var(--ink3)}
.bdg-tbl{width:100%;border-collapse:collapse;font-size:14px}
.bdg-tbl th{text-align:left;font-size:13px;font-weight:700;color:var(--ink3);padding:12px 12px 10px 0;border-bottom:1px solid var(--hair2)}
.bdg-tbl td{margin:0;background:none;display:table-cell;padding:12px 12px 12px 0;border-bottom:1px solid var(--hair);vertical-align:middle}
.bdg-tbl td.bdg-tg{font-weight:700;color:var(--brand-900);white-space:nowrap}
.bdg-tbl td.bdg-tn{white-space:nowrap}
.bdg-tbl td.bdg-tn>span{display:flex;align-items:center;gap:10px;font-weight:700}
.bdg-tbl td.bdg-tn .bdg-em{width:30px;height:30px}
.bdg-tbl td.bdg-ts{font-size:13px;color:var(--ink2)}
.bdg-tbl td.bdg-tt,.bdg-tbl td.bdg-to{white-space:nowrap;font-size:13px;color:var(--ink2)}
.bdg-tbl tr.bdg-topt td{color:var(--ink3)}
.bdg-q{list-style:none;margin:0;padding:0;counter-reset:bq}
.bdg-q li{display:grid;grid-template-columns:48px 1fr;gap:4px 0;padding:20px 0;border-bottom:1px solid var(--hair);counter-increment:bq}
