.c11-sov.on{opacity:1;visibility:visible}
.c11-sbox{width:min(720px,100%);transform:translateY(-18px);transition:transform .32s cubic-bezier(.2,.7,.2,1)}
.c11-sov.on .c11-sbox{transform:none}
.c11-sf{display:flex;align-items:center;gap:8px;height:60px;padding:0 8px 0 22px;background:#fff;border:1px solid #d5e2ec;border-radius:999px;box-shadow:0 12px 40px rgba(0,37,60,.12)}
.c11-sf:focus-within{border-color:#004772}
.c11-sf svg.c11-ic{flex:none;color:#5b5b5b}
.c11-sf input{-webkit-appearance:none;appearance:none;box-shadow:none!important;border-radius:0!important;padding:0!important;flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;font:inherit;font-size:17px;color:#2b2b2b}
.c11-sf input::placeholder{color:#8a99a6}
.c11-sf button[type=submit]{flex:none;width:44px;height:44px;border-radius:50%;border:0;background:#004772;color:#fff;display:grid;place-items:center;cursor:pointer}
.c11-sf button[type=submit]:hover{background:#003f6d}
.c11-x{flex:none;border:0;background:transparent;color:#5b5b5b;font:inherit;font-size:13px;font-weight:600;cursor:pointer;padding:6px 8px}
.c11-x:hover{color:#2b2b2b}
.c11-hint{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:16px 6px 0;font-size:13px;color:#5b5b5b}
.c11-hint b{font-weight:700;margin-right:4px}
.c11-hint a{display:inline-flex;height:30px;align-items:center;padding:0 12px;border-radius:999px;background:rgba(255,255,255,.85);border:1px solid #d5e2ec;color:#2b2b2b;text-decoration:none;font-weight:600}
.c11-hint a:hover{border-color:#004772;color:#004772}
body.c11-lock{overflow:hidden}
@media(prefers-reduced-motion:reduce){.c11-sov,.c11-sbox{transition:none}}
/* ==== 시안 style 블록 30 ==== */
/* 11/19 Idea Board 한 줄 게시 (c12-): 자세한 내용 칸 없앰, 포스트잇 모양은 그대로 */
#ideas .note-new .ndesc,#ideas .note-new label[for=noteDesc]{display:none!important}
#ideas .note-new #noteText{flex:1!important;min-height:96px!important;font-size:18px!important;line-height:1.5!important;resize:none}
#idea .iddesc{display:none!important}
#ieForm .c12-hide{display:none!important}
/* ==== 시안 style 블록 31 ==== */
#noteCat[aria-invalid=true]{outline:2px solid #c0392b;outline-offset:1px}
/* ==== 시안 style 블록 32 ==== */
/* 11/19 Idea Board: 포스트잇 쓰기 칸과 아래 탭·보드 간격 넓힘 (30→64px) */
#ideas .ib-main>.composer{margin-bottom:96px!important}
@media(max-width:600px){#ideas .ib-main>.composer{margin-bottom:56px!important}}
/* 포스트잇 쓰기 칸: 보드 포스트잇과 같은 크기(약 248×200px) */
#ideas .note-new{width:248px!important;min-height:200px!important;height:200px}
#ideas .note-new #noteText{min-height:0!important}
/* ==== 시안 style 블록 33 ==== */
/* ===== 11/19 15:26 희재 요청 반영 (v19) ===== */
/* --- 1) 배지 화면 A안 확정·다듬기 (ba-) --- */
#badges .ba-all>header{border-bottom:0;padding-bottom:4px}
.ba-tabs{display:flex;flex-wrap:wrap;gap:0 26px;border-bottom:1px solid var(--hair2)}
.ba-tabs button{all:unset;box-sizing:border-box;cursor:pointer;display:inline-flex;align-items:baseline;gap:6px;padding:10px 0 12px;margin-bottom:-1px;border-bottom:2px solid transparent;font-size:15px;font-weight:700;color:var(--ink2)}
.ba-tabs button span{font-size:12px;font-weight:700;color:var(--ink3);font-variant-numeric:tabular-nums}
.ba-tabs button:hover{color:#004772}
.ba-tabs button[aria-selected="true"]{color:#004772;border-color:#004772}
.ba-tabs button[aria-selected="true"] span{color:#004772}
.ba-tabs button:focus-visible{outline:2px solid #004772;outline-offset:2px;border-radius:4px}
.ba-next{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-bottom:1px solid var(--hair2)}
.ba-next>li{display:flex;flex-direction:column;gap:10px;padding:24px 28px 22px 0;min-width:0}
.ba-next>li+li{padding-left:28px;border-left:1px solid var(--hair)}
.ba-next button{all:unset;box-sizing:border-box;cursor:pointer;display:grid;grid-template-columns:64px minmax(0,1fr);gap:16px;align-items:center;width:100%}
.ba-next button:focus-visible{outline:3px solid #004772;outline-offset:4px;border-radius:8px}
.ba-next .bdg-em{width:64px;height:64px;transition:transform .35s var(--ease)}
.ba-next button:hover .bdg-em{transform:translateY(-3px)}
.ba-ng{display:block;font-size:12px;font-weight:700;color:var(--ink3)}
.ba-next b{display:block;margin-top:1px;font-size:16px;font-weight:800;color:var(--brand-900);word-break:keep-all}
.ba-next button:hover b{color:#004772}
.ba-nd{display:block;margin:2px 0 10px;font-size:13px;color:var(--ink2)}
.ba-nd em{font-style:normal;font-weight:800;color:#004772}
.ba-nb{display:block;height:6px;border-radius:3px;background:#e6edf1;overflow:hidden}
.ba-nb i{display:block;height:100%;border-radius:3px;background:linear-gradient(90deg,rgba(0,71,114,.45),#004772)}
.ba-go{align-self:flex-start;margin-left:80px;font-size:13px;font-weight:700;color:#004772;text-decoration:none}
.ba-go:hover{text-decoration:underline}
.ba-none{margin:20px 0;font-size:14px;color:var(--ink2)}
.ba-k{padding-top:26px}
.ba-row{display:grid;grid-template-columns:128px minmax(0,1fr);gap:0 20px;align-items:start;padding:12px 0 8px;border-top:1px solid var(--hair)}
.ba-k p+.ba-row{margin-top:14px;border-top-color:var(--hair2)}
.ba-row h4{margin:0;padding-top:30px;font-size:15px;font-weight:800;color:var(--ink,#1c2a36);display:flex;flex-direction:column;gap:2px}
.ba-row h4 span{font-size:12px;font-weight:700;color:var(--ink3);font-variant-numeric:tabular-nums}
#badges .ba-track{display:flex!important;flex-wrap:wrap;gap:0!important;list-style:none;margin:0;padding:0!important}
.ba-c{position:relative;width:132px;list-style:none}
.ba-c+.ba-c::before{content:"";position:absolute;left:-20px;top:43px;width:40px;height:2px;border-radius:1px;background:#dbe4ec}
.ba-c.is-got+.ba-c.is-got::before{background:#004772}
.ba-c.is-got+.ba-c.is-next::before{background:linear-gradient(90deg,#004772 0 50%,#dbe4ec 50% 100%)}
.ba-c .bdg-cell b{word-break:keep-all;overflow-wrap:anywhere}
.ba-c.is-next .bdg-cell b{color:#004772}
.ba-c.is-lock .bdg-cell b{color:var(--ink3)}
.ba-sub{display:flex;flex-direction:column;align-items:center}
.ba-pg{display:block;width:56px;height:4px;margin:3px 0 3px;border-radius:2px;background:#e6edf1;overflow:hidden}
.ba-pg i{display:block;height:100%;border-radius:2px;background:#004772}
.ba-pn{font-size:12px;font-weight:700;color:#004772;font-variant-numeric:tabular-nums}
#badges .ba-hid{display:grid!important;grid-template-columns:repeat(auto-fill,minmax(132px,1fr))!important;gap:8px 0!important;margin:14px 0 0;padding:12px 0 0!important;border-top:1px solid var(--hair2);list-style:none}
#badges .ba-hid .ba-c{width:auto}
#badges .ba-hid .ba-c::before{display:none}
@media(max-width:900px){.ba-next{grid-template-columns:1fr}.ba-next>li{padding-right:0}.ba-next>li+li{padding-left:0;border-left:0;border-top:1px solid var(--hair)}}
@media(max-width:700px){.ba-row{grid-template-columns:1fr}.ba-row h4{padding-top:0;flex-direction:row;align-items:baseline;gap:8px;margin-bottom:6px}.ba-c{width:33.33%}.ba-c+.ba-c::before{display:none}.ba-tabs{gap:0 18px}.ba-tabs button{font-size:14px}}

/* --- 2) 검색: 결과도 블러 화면 안에서 (sx-) --- */
.hd .util [data-sxopen]{cursor:pointer}
.c11-sov{padding-top:72px}
.c11-hint[hidden]{display:none}
.c11-hint button,.sx-sug button{-webkit-appearance:none;appearance:none;font:inherit;cursor:pointer;display:inline-flex;height:30px;align-items:center;padding:0 12px;border-radius:999px;background:rgba(255,255,255,.85);border:1px solid #d5e2ec;color:#2b2b2b;font-size:13px}
.c11-hint button:hover,.sx-sug button:hover{border-color:#004772;color:#004772}
.c11-hint button.sx-rm{background:none;border:0;padding:0 4px;margin-left:2px;color:#5b5b5b;text-decoration:underline;text-underline-offset:3px}
.sx-clr{flex:none;width:28px;height:28px;border-radius:50%;border:0;background:#eef3f7;color:#5b5b5b;font-size:12px;line-height:1;cursor:pointer}
.sx-clr:hover{background:#e0e9f0}
.sx-clr[hidden]{display:none}
.sx-res{margin-top:12px;background:#fff;border:1px solid #d5e2ec;border-radius:22px;box-shadow:0 24px 60px -30px rgba(0,37,60,.4);max-height:calc(100vh - 220px);overflow:auto;overscroll-behavior:contain;padding-bottom:10px}
.sx-res[hidden]{display:none}
.sx-top{position:sticky;top:0;z-index:1;display:flex;align-items:center;gap:8px 16px;flex-wrap:wrap;padding:14px 22px 12px;background:#fff;border-bottom:1px solid #e8eef3;border-radius:22px 22px 0 0}
.sx-top p{margin:0;font-size:13px;color:#5b5b5b;white-space:nowrap}
.sx-top p b{color:#2b2b2b}
.sx-fs{display:flex;flex-wrap:wrap;gap:6px}
.sx-fs button{all:unset;box-sizing:border-box;cursor:pointer;display:inline-flex;align-items:center;gap:5px;height:28px;padding:0 11px;border-radius:999px;border:1px solid #d5e2ec;font-size:13px;font-weight:600;color:#2b2b2b}
.sx-fs button small{font-size:12px;font-weight:600;color:#5b5b5b}
.sx-fs button:hover{border-color:#004772}
.sx-fs button[aria-pressed="true"]{background:#004772;border-color:#004772;color:#fff}
.sx-fs button[aria-pressed="true"] small{color:rgba(255,255,255,.82)}
.sx-fs button:focus-visible,.sx-more:focus-visible{outline:2px solid #004772;outline-offset:2px}
.sx-g{padding:10px 0 0}
.sx-g h3{display:flex;gap:6px;margin:0;padding:6px 22px;font-size:12px;font-weight:700;letter-spacing:0;color:#5b6f80}
.sx-g h3 span{color:#004772}
.sx-row{display:flex;align-items:center;gap:14px;padding:10px 22px;text-decoration:none;color:#2b2b2b}
.sx-row:hover,.sx-row:focus-visible{background:#f3f6f8;outline:0}
.sx-row:focus-visible{box-shadow:inset 3px 0 0 #004772}
.sx-t{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.sx-t b{font-size:15px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sx-t>span{font-size:13px;color:#5b5b5b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sx-row mark{background:#fff1b8;color:inherit;border-radius:2px;padding:0 1px}
.sx-ty{flex:none;font-size:12px;font-weight:600;color:#5b6f80}
.sx-more{all:unset;box-sizing:border-box;cursor:pointer;display:block;padding:6px 22px 8px;font-size:13px;font-weight:700;color:#004772}
.sx-more:hover{text-decoration:underline}
.sx-empty{padding:30px 24px 16px;text-align:center}
.sx-empty b{font-size:16px;color:#2b2b2b}
.sx-empty p{margin:8px 0 16px;font-size:14px;color:#5b5b5b}
.sx-sug{display:flex;justify-content:center;flex-wrap:wrap;gap:8px;margin-bottom:18px}
.sx-idea{font-size:14px;font-weight:700;color:#004772;text-decoration:none}
.sx-idea:hover{text-decoration:underline}
.sx-foot{display:flex;align-items:center;gap:14px;margin:12px 8px 0;font-size:12px;color:#5b5b5b}
.sx-foot kbd{display:inline-block;min-width:20px;box-sizing:border-box;padding:1px 5px;margin-right:4px;border:1px solid #c3d1dc;border-radius:5px;background:rgba(255,255,255,.85);font:inherit;font-size:11px;text-align:center}
.sx-foot .c11-x{margin-left:auto}
@media(max-width:600px){.sx-foot span{display:none}.c11-sov{padding-top:60px}.sx-res{max-height:calc(100vh - 190px)}}

/* 제이콥의 법칙 검토: 배지 상세 게이지도 화면의 다른 게이지와 같은 파란 계열 */
#bdgDlg .b3-bar i{background:linear-gradient(90deg,rgba(0,71,114,.45),#004772)!important}
/* --- 3) Case Library: 활용 제품 필터를 업종 알약과 같은 높이에 (cz-) --- */
.ca-fwrap[hidden]{display:none!important}
.cz-f{display:grid;grid-template-columns:76px minmax(0,1fr);gap:0 8px;align-items:start;margin-top:12px}
.cz-f+.cz-f{margin-top:8px}
.cz-l{display:flex;align-items:center;height:38px;font-size:13px;font-weight:700;color:var(--ink2)}
.cz-f .ca-chips{margin:0}
.cz-prods{display:flex;flex-wrap:wrap;gap:6px;align-items:center;min-height:38px}
.cz-chip{-webkit-appearance:none;appearance:none;display:inline-flex;align-items:center;gap:7px;height:34px;padding:0 10px 0 9px;border:1px solid #d6e1e9;border-radius:9px;background:#fff;font:inherit;font-size:14px;color:var(--ink);cursor:pointer;white-space:nowrap}
.cz-chip .pc{height:auto;gap:0}
.cz-chip small{font-size:12px;color:var(--ink3,#888)}
.cz-chip .cz-ck{display:none;width:14px;height:14px;margin:0 -4px 0 -4px;fill:none;stroke:#004772;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.cz-chip:hover{border-color:#004772}
.cz-chip[aria-pressed="true"]{background:#e6edf1;border-color:#004772;color:#004772;-webkit-text-stroke:.4px currentColor}
.cz-chip[aria-pressed="true"] .pc{display:none}
.cz-chip[aria-pressed="true"] .cz-ck{display:block}
.cz-chip[aria-pressed="true"] small{color:#004772}
.cz-chip:focus-visible{outline:2px solid #003f6d;outline-offset:2px}
#cases .ca-bar{margin-top:14px}
@media(max-width:700px){.cz-f{grid-template-columns:1fr}.cz-l{height:auto;margin:4px 0 6px}}

/* --- 4) Idea Board 문구·흐름 (ib2-) --- */
#ideas .note-new .row{gap:8px}
#ideas .note-new #noteCat{min-width:0;flex:0 1 auto}
.ib2-cnt{margin-left:auto;font-size:11px;font-weight:600;color:rgba(60,48,10,.55);font-variant-numeric:tabular-nums;white-space:nowrap}
.ib2-h{display:block;margin-top:3px;font-size:12px;font-weight:400;color:var(--ink3);line-height:1.4}
#idea .idmini .iml:has(.ib2-h){display:block}
/* ==== 시안 style 블록 34 ==== */
/* 11/19 16:36 희재 수정 */
/* 배지 사이: 게이지 선 대신 짙은 회색 > 모양 */
.ba-c+.ba-c::before,.ba-c.is-got+.ba-c.is-got::before,.ba-c.is-got+.ba-c.is-next::before{left:-6px;top:38px;width:9px;height:9px;border-radius:1px;background:none!important;border-top:2.5px solid #5f6b76;border-right:2.5px solid #5f6b76;transform:rotate(45deg)}
.ba-ph{display:block;width:100%;height:100%}
