.ba-next{gap:16px;border-bottom:0;margin-top:16px}
.ba-next>li,.ba-next>li+li{padding:22px 24px 20px;border:1px solid #d6e1e9;border-left:1px solid #d1d1d1;border-top:1px solid #d1d1d1;border-radius:16px;background:#fff;transition:border-color .2s,box-shadow .2s}
.ba-next>li:hover{border-color:#004772;box-shadow:0 10px 24px -18px rgba(0,37,60,.35)}
@media(max-width:900px){.ba-next{gap:12px}.ba-next>li,.ba-next>li+li{padding:18px 18px 16px}}
/* 통합 검색: 안내는 검색창 위, 닫기는 밑줄 글자, 추천 단어와 간격 넓게 */
.c11-sbox .sx-foot{margin:0 8px 14px}
