.cz-chip[hidden]{display:none}
.cz-more{-webkit-appearance:none;appearance:none;border:0;background:none;font:inherit;font-size:14px;color:var(--ink2);text-decoration:underline;text-underline-offset:3px;cursor:pointer;padding:6px 4px;white-space:nowrap}
.cz-more small{font-size:12px;color:#004772}
.cz-more:hover{color:#004772}
.cz-more:focus-visible{outline:2px solid #003f6d;outline-offset:2px;border-radius:4px}
/* ==== 시안 style 블록 35 ==== */
/* 11/19 16:49 희재 수정 */
