/* c20 23:29 Idea Board 진행 방법 제목, 2·3단계 왼쪽으로 */
.c20-fw{flex:1;min-width:260px;align-self:center}
.c20-fw .iflow.xf{min-width:0;width:100%}
.c20-ft{margin:0 0 30px;font-size:17px;font-weight:800;color:var(--brand-900,#004772);letter-spacing:-.2px}
