.pn-rib .pn-tape{padding-top:7px;padding-bottom:7px}
/* c22 23:58 함께해요 사람 = 프로필 배지 */
.avs i.c22-b{width:24px;height:24px;background:none!important;border:0;border-radius:0;display:block}
.avs i.c22-b svg{display:block;width:100%;height:100%;overflow:visible}
.avs i.c22-b+i.c22-b{margin-left:-4px}
/* c23 23:58 희재: Idea Board 탭 = 서류철 인덱스 탭(위로 튀어나옴, 고르면 아래 보드가 펼쳐짐) */
#ideas .sec-h:has(.itabs){margin-bottom:0!important;align-items:flex-end}
#ideas .sec-h:has(.itabs) .psearch{margin-bottom:12px}
#ideas .itabs{background:none!important;padding:0 0 0 0;gap:3px;border-radius:0;align-items:flex-end;position:relative;z-index:2}
#ideas .itabs button{height:42px;padding:0 22px;border-radius:12px 12px 0 0;background:#e6edf1;color:#5b5b5b;box-shadow:inset 0 -6px 8px -6px rgba(0,40,70,.12);transform:translateY(0);transition:height .2s,background .2s,color .2s,transform .2s}
#ideas .itabs button:hover:not([aria-selected=true]){background:#e6edf2;height:46px}
#ideas .itabs button[aria-selected=true]{height:50px;background:#f3f6f8;color:#004772;box-shadow:0 -3px 8px -4px rgba(0,40,70,.14)}
#ideas .itabs button span{background:rgba(255,255,255,.75)}
#ideas .itabs button[aria-selected=true] span{background:#004772;color:#fff}
