/* 댓글 배경 없앰 */
#idea .idcmt{background:none!important;padding-left:0;padding-right:0}
/* c31 00:30 아이디어 상세: 보드와 같은 포스트잇 + 옆에 가로 진행 단계 */
#idea .idboard>.pn{position:relative;box-sizing:border-box;min-height:200px}
#idea .idboard>.pn .c31-t{margin:0;font:inherit}
#idea .idboard>.pn .c31-t b{display:block}
#idea .pn .pn-tape{padding:5px 44px;top:14px;right:-44px;font-size:10px;gap:4px}
