#idea .pn .pn-pill.on{border-color:var(--fillc)}
#idea .pn .who{display:flex!important;align-items:center;gap:5px;font-size:12px;color:var(--ink2);margin-top:6px}
#idea .pn .who b{font-weight:700;color:var(--ink)}
