/* c32 00:30 Teams로 이어지는 단추·만들기 중지 = 알약 */
body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.askbtn,body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.imteams:not(.pri),body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.imstopbtn{display:inline-flex!important;align-items:center;justify-content:center;width:auto!important;height:36px!important;min-height:36px;padding:0 18px!important;border:1px solid rgba(0,71,114,.35)!important;border-radius:999px!important;background:#fff!important;color:#004772!important;text-decoration:none!important;font-size:13.5px!important;font-weight:700!important;box-shadow:none!important}
body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.askbtn:hover,body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.imteams:not(.pri):hover,body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.imstopbtn:hover{background:#f3f6f8!important;border-color:#004772!important}
body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.askbtn::after,body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.imteams:not(.pri)::after,body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.imstopbtn::after,body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.askbtn::before,body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.imteams:not(.pri)::before,body :is(#agent,#skill,#htmlitem,#case,#idea,#me,#market,#home) button.btn.imstopbtn::before{display:none!important}
