#notifPanel,#meDrawer{background:rgba(255,255,255,.93)!important;-webkit-backdrop-filter:blur(24px)!important;backdrop-filter:blur(24px)!important;border-color:rgba(0,0,0,.05)!important;box-shadow:0 0 0 1px rgba(0,0,0,.05) inset,0 30px 70px -28px rgba(0,0,0,.32)!important}
